import { addPropertyControls, ControlType, RenderTarget } from "framer"
import { cubicBezier } from "framer-motion"
import { useId, useLayoutEffect, useMemo, useRef } from "react"

const ease = cubicBezier(0.7, 0, 0.7, 1)

enum Pattern {
    Grid = "grid",
    Checkerboard = "checkerboard",
    HorizontalLines = "horizontalLines",
    VerticalLines = "verticalLines",
    DiagonalLines = "diagonalLines",
    Dots = "dots",
    Triangles = "triangles",
    Custom = "custom",
}

enum CanvasPreview {
    Play = "play",
    Pause = "pause",
}

const IMAGE_SIZING_MAP = {
    fill: "cover",
    fit: "contain",
    stretch: "100% 100%",
}

const POSITION_MAP = {
    topLeft: "0 0",
    topCenter: "50% 0",
    topRight: "100% 0",
    left: "0 50%",
    center: "50% 50%",
    right: "100% 50%",
    bottomLeft: "0 100%",
    bottomCenter: "50% 100%",
    bottomRight: "100% 100%",
}

const CANVAS_PREVIEW_DURATION = 4000
const CANVAS_PREVIEW_REACH = 0.28

/**
 * @framerSupportedLayoutWidth fixed
 * @framerSupportedLayoutHeight fixed
 *
 * @framerDisableUnlink
 *
 * @framerIntrinsicWidth 600
 * @framerIntrinsicHeight 450
 */
export default function ShimmerGrid({
    onCanvas,
    color,
    hoverColor,
    hoverSize,
    hoverShape,
    patternPreset,
    flip,
    lineWidth,
    customPatternImage,
    customPatternSizing,
    tileSize,
    customPatternMode,
    customPatternPosition,
    dotSize,
    radius,
    smoothing,
    style,
}) {
    const isCanvas = RenderTarget.current() === RenderTarget.canvas
    const isCustom = patternPreset === Pattern.Custom
    const bgPosition =
        isCustom && customPatternSizing !== "stretch"
            ? POSITION_MAP[customPatternPosition]
            : POSITION_MAP.center

    const { bgImage, bgSize, bgRepeat } = useMemo(() => {
        let bgImage = ""
        let bgSize = `${tileSize}px ${tileSize}px`
        let bgRepeat = "repeat"

        switch (patternPreset) {
            case Pattern.Grid:
                bgImage = `repeating-conic-gradient(at ${lineWidth}px ${lineWidth}px, [color] 0deg 90deg, transparent 90deg 180deg, [color] 180deg 360deg)`
                break
            case Pattern.Checkerboard:
                bgImage = flip
                    ? `repeating-conic-gradient([color] 0% 25%, transparent 0% 50%)`
                    : `repeating-conic-gradient(transparent 0% 25%, [color] 0% 50%)`
                break
            case Pattern.HorizontalLines:
                bgImage = `linear-gradient(to top, [color] ${lineWidth}px, transparent ${lineWidth}px)`
                break
            case Pattern.VerticalLines:
                bgImage = `linear-gradient(to left, [color] ${lineWidth}px, transparent ${lineWidth}px)`
                break
            case Pattern.DiagonalLines: {
                const w = lineWidth / 2
                const sideLength = getSideLength(tileSize * 2)
                bgImage = `linear-gradient(to top ${
                    flip ? "left" : "right"
                }, [color] ${w}px, transparent ${w}px, transparent calc(50% - ${w}px), [color] calc(50% - ${w}px), [color] calc(50% + ${w}px), transparent calc(50% + ${w}px), transparent calc(100% - ${w}px), [color] calc(100% - ${w}px), [color] 100%)`
                bgSize = `${sideLength}px ${sideLength}px`
                break
            }
            case Pattern.Dots:
                bgImage = `radial-gradient([color] ${dotSize / 2 - 0.4}px, transparent ${
                    dotSize / 2 + 0.4
                }px)`
                break
            case Pattern.Triangles:
                bgImage = `linear-gradient(${
                    flip ? -45 : 45
                }deg, transparent calc(50% - 0.1px), [color] calc(50% + 0.1px))`
                break
            case Pattern.Custom:
                bgImage = `url("${customPatternImage?.src}")`
                if (customPatternSizing !== "tile") {
                    bgRepeat = "no-repeat"
                    bgSize = IMAGE_SIZING_MAP[customPatternSizing]
                }
                break
        }

        return { bgImage, bgSize, bgRepeat }
    }, [
        patternPreset,
        lineWidth,
        flip,
        tileSize,
        dotSize,
        customPatternImage,
        customPatternSizing,
    ])

    const { hoverStyle, hoverSizeValue } = useMemo(() => {
        if (hoverShape === "glow") {
            const gradientPoints: string[] = []
            for (let i = 0; i < 15; i++) {
                const normalized = mapRange(i, 0, 14, 0, 1)
                gradientPoints.push(
                    `rgba(255, 255, 255, ${ease(1 - normalized)}) ${mapRange(i, 0, 14, 0, 100)}%`
                )
            }

            return {
                hoverStyle: {
                    maskImage: `radial-gradient(closest-side, ${gradientPoints.join(", ")})`,
                },
                hoverSizeValue: hoverSize * 2,
            }
        }

        if (hoverShape === "circle") {
            return {
                hoverStyle: { borderRadius: "50%" },
                hoverSizeValue: hoverSize,
            }
        }

        return { hoverStyle: {}, hoverSizeValue: hoverSize }
    }, [hoverShape, hoverSize])

    const previewId = useId()
    const containerRef = useRef<HTMLDivElement>(null)
    const previewStyleRef = useRef<HTMLStyleElement>(null)
    const isPreviewPlaying = isCanvas && onCanvas !== CanvasPreview.Pause

    useLayoutEffect(() => {
        if (!isPreviewPlaying) {
            if (previewStyleRef.current) previewStyleRef.current.textContent = ""
            return
        }

        let animationFrameId: number
        let size = { width: 0, height: 0 }

        const measure = () => {
            if (!containerRef.current) return
            const rect = containerRef.current.getBoundingClientRect()
            size = { width: rect.width, height: rect.height }
        }
        measure()

        const resizeObserver =
            typeof ResizeObserver !== "undefined" ? new ResizeObserver(measure) : null
        if (resizeObserver && containerRef.current) {
            resizeObserver.observe(containerRef.current)
        }

        const startTime = performance.now()

        const tick = (now: number) => {
            animationFrameId = requestAnimationFrame(tick)
            if (!previewStyleRef.current) return

            const t =
                ((now - startTime) % CANVAS_PREVIEW_DURATION) / CANVAS_PREVIEW_DURATION
            const angle = t * Math.PI * 2

            const normalizedX = Math.sin(angle)
            const normalizedY = Math.sin(angle) * Math.cos(angle)

            const offsetX = (normalizedX * size.width * CANVAS_PREVIEW_REACH).toFixed(2)
            const offsetY = (normalizedY * size.height * CANVAS_PREVIEW_REACH).toFixed(2)

            previewStyleRef.current.textContent = `[data-shimmer-preview="${previewId}"] { transform: translate(-50%, -50%) translate(${offsetX}px, ${offsetY}px) !important; }`
        }

        animationFrameId = requestAnimationFrame(tick)

        return () => {
            cancelAnimationFrame(animationFrameId)
            resizeObserver?.disconnect()
        }
    }, [isPreviewPlaying, previewId])

    useLayoutEffect(() => {
        if (isCanvas || typeof window === "undefined") return

        const stiffness = mapRange(
            Math.min(Math.max(Number(smoothing) || 0, 0), 100),
            0,
            100,
            2000,
            50
        )
        const damping = 100
        let target: { x: number; y: number } | null = null
        let pos = { x: 0, y: 0 }
        let vel = { x: 0, y: 0 }
        let last = 0
        let frame = 0

        const write = () => {
            if (!previewStyleRef.current) return
            previewStyleRef.current.textContent = `[data-shimmer-preview="${previewId}"] { transform: translate(${pos.x.toFixed(2)}px, ${pos.y.toFixed(2)}px) translate(-50%, -50%) !important; }`
        }

        const step = (now: number) => {
            frame = 0
            if (!target) return
            let dt = Math.min((now - (last || now)) / 1000, 0.064)
            last = now
            const sub = Math.max(1, Math.ceil(dt / 0.004))
            const h = dt / sub
            for (let i = 0; i < sub; i++) {
                vel.x += ((target.x - pos.x) * stiffness - vel.x * damping) * h
                vel.y += ((target.y - pos.y) * stiffness - vel.y * damping) * h
                pos.x += vel.x * h
                pos.y += vel.y * h
            }
            write()
            const settled =
                Math.abs(target.x - pos.x) < 0.1 &&
                Math.abs(target.y - pos.y) < 0.1 &&
                Math.abs(vel.x) < 0.1 &&
                Math.abs(vel.y) < 0.1
            if (settled) {
                pos = { ...target }
                vel = { x: 0, y: 0 }
                write()
                last = 0
                return
            }
            frame = requestAnimationFrame(step)
        }

        const onMove = (event: PointerEvent) => {
            const el = containerRef.current
            if (!el) return
            const rect = el.getBoundingClientRect()
            const next = { x: event.clientX - rect.left, y: event.clientY - rect.top }
            if (!target) {
                pos = { ...next }
                vel = { x: 0, y: 0 }
                target = next
                write()
                return
            }
            target = next
            if (!frame) frame = requestAnimationFrame(step)
        }

        window.addEventListener("pointermove", onMove, { passive: true })
        return () => {
            window.removeEventListener("pointermove", onMove)
            if (frame) cancelAnimationFrame(frame)
            if (previewStyleRef.current) previewStyleRef.current.textContent = ""
        }
    }, [isCanvas, smoothing, previewId])

    return (
        <div
            ref={containerRef}
            style={{
                position: "relative",
                borderRadius: radius,
                overflow: "hidden",
                backgroundImage: isCustom
                    ? ""
                    : bgImage.replace(/\[color\]/g, color),
                backgroundSize: bgSize,
                backgroundPosition: bgPosition,
                backgroundRepeat: bgRepeat,
                ...style,
            }}
        >
            {isCustom && (
                <div
                    style={{
                        position: "absolute",
                        inset: 0,
                        backgroundColor: color,
                        maskImage: bgImage,
                        maskSize: bgSize,
                        maskPosition: bgPosition,
                        maskRepeat: bgRepeat,
                        maskMode: customPatternMode,
                    }}
                />
            )}
            <div
                style={{
                    position: "absolute",
                    inset: 0,
                    maskImage: isCustom
                        ? bgImage
                        : bgImage.replace(/\[color\]/g, "white"),
                    maskSize: bgSize,
                    maskPosition: bgPosition,
                    maskRepeat: bgRepeat,
                    maskMode: isCustom ? customPatternMode : undefined,
                    WebkitMaskImage: isCustom
                        ? bgImage
                        : bgImage.replace(/\[color\]/g, "white"),
                    WebkitMaskSize: bgSize,
                    WebkitMaskPosition: bgPosition,
                    WebkitMaskRepeat: bgRepeat,
                    WebkitMaskMode: isCustom ? customPatternMode : undefined,
                }}
            >
                <style ref={previewStyleRef}></style>
                <div
                    data-shimmer-preview={previewId}
                    style={{
                        position: "absolute",
                        top: isCanvas ? "50%" : 0,
                        left: isCanvas ? "50%" : 0,
                        transform: isCanvas
                            ? "translate(-50%, -50%)"
                            : "translate(-9999px, -9999px)",
                        width: hoverSizeValue,
                        height: hoverSizeValue,
                        backgroundColor: hoverColor,
                        ...hoverStyle,
                    }}
                />
            </div>
        </div>
    )
}

ShimmerGrid.displayName = "Shimmer Grid"

addPropertyControls(ShimmerGrid, {
    onCanvas: {
        type: ControlType.Enum,
        title: "On canvas",
        defaultValue: CanvasPreview.Play,
        options: [CanvasPreview.Play, CanvasPreview.Pause],
        optionTitles: ["Play", "Pause"],
        displaySegmentedControl: true,
    },
    color: {
        type: ControlType.Color,
        title: "Color",
        defaultValue: "rgba(255, 255, 255, 0.05)",
    },
    hoverColor: {
        type: ControlType.Color,
        title: "Hover color",
        defaultValue: "#178BFF",
    },
    hoverSize: {
        type: ControlType.Number,
        title: "Hover size",
        defaultValue: 400,
        min: 1,
        max: 2000,
        step: 1,
    },
    hoverShape: {
        type: ControlType.Enum,
        defaultValue: "glow",
        options: ["glow", "circle"],
        optionTitles: ["Glow", "Circle"],
        displaySegmentedControl: true,
        title: "Shape",
    },
    patternPreset: {
        type: ControlType.Enum,
        defaultValue: Pattern.Dots,
        options: Object.values(Pattern),
        optionTitles: [
            "Grid",
            "Checkerboard",
            "Horizontal lines",
            "Vertical lines",
            "Diagonal lines",
            "Dots",
            "Triangles",
            "Custom",
        ],
        title: "Pattern",
    },
    customPatternImage: {
        type: ControlType.ResponsiveImage,
        title: "Image",
        hidden: (props) => props.patternPreset !== Pattern.Custom,
    },
    customPatternSizing: {
        type: ControlType.Enum,
        defaultValue: "tile",
        options: ["fill", "fit", "stretch", "tile"],
        optionTitles: ["Fill", "Fit", "Stretch", "Tile"],
        title: "Sizing",
        hidden: (props) => props.patternPreset !== Pattern.Custom,
    },
    flip: {
        type: ControlType.Boolean,
        title: "Flip",
        defaultValue: false,
        hidden: (props) =>
            props.patternPreset !== Pattern.Checkerboard &&
            props.patternPreset !== Pattern.Triangles &&
            props.patternPreset !== Pattern.DiagonalLines,
    },
    lineWidth: {
        type: ControlType.Number,
        title: "Line width",
        defaultValue: 2,
        min: 1,
        step: 1,
        displayStepper: true,
        hidden: (props) =>
            props.patternPreset !== Pattern.HorizontalLines &&
            props.patternPreset !== Pattern.VerticalLines &&
            props.patternPreset !== Pattern.DiagonalLines &&
            props.patternPreset !== Pattern.Grid,
    },
    tileSize: {
        type: ControlType.Number,
        title: "Tile size",
        defaultValue: 10,
        min: 1,
        step: 1,
        hidden: (props) =>
            props.patternPreset === Pattern.Custom &&
            props.customPatternSizing !== "tile",
    },
    dotSize: {
        type: ControlType.Number,
        title: "Dot size",
        defaultValue: 3,
        min: 1,
        step: 1,
        displayStepper: true,
        hidden: (props) => props.patternPreset !== Pattern.Dots,
    },
    customPatternPosition: {
        type: ControlType.Enum,
        defaultValue: "center",
        options: [
            "topLeft",
            "topCenter",
            "topRight",
            "left",
            "center",
            "right",
            "bottomLeft",
            "bottomCenter",
            "bottomRight",
        ],
        optionTitles: [
            "Top left",
            "Top center",
            "Top right",
            "Left",
            "Center",
            "Right",
            "Bottom left",
            "Bottom center",
            "Bottom right",
        ],
        title: "Position",
        hidden: (props) =>
            props.patternPreset !== Pattern.Custom ||
            props.customPatternSizing === "stretch",
    },
    customPatternMode: {
        type: ControlType.Enum,
        defaultValue: "alpha",
        options: ["alpha", "luminance"],
        optionTitles: ["Alpha", "Luminance"],
        title: "Mode",
        hidden: (props) => props.patternPreset !== Pattern.Custom,
    },
    smoothing: {
        type: ControlType.Number,
        title: "Smoothing",
        defaultValue: 50,
        min: 0,
        max: 100,
        step: 1,
    },
    radius: {
        type: ControlType.BorderRadius,
        title: "Radius",
        defaultValue: "0px",
        description:
            "More components at [Framer University](https://frameruni.link/cc).",
    },
})

function getSideLength(hypotenuseLength) {
    if (
        typeof hypotenuseLength !== "number" ||
        isNaN(hypotenuseLength) ||
        hypotenuseLength <= 0
    ) {
        return hypotenuseLength
    }

    const sideLength = Math.sqrt(Math.pow(hypotenuseLength, 2) / 2)

    return Number(sideLength.toFixed(2))
}

function mapRange(value, fromLow, fromHigh, toLow, toHigh) {
    if (fromLow === fromHigh) {
        return toLow
    }
    const percentage = (value - fromLow) / (fromHigh - fromLow)
    return toLow + percentage * (toHigh - toLow)
}
